package org.apache.commons.codec.binary;

import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;

/**
 * Converts between byte arrays and strings of "0"s and "1"s.
 *
 * <p>
 * This class is immutable and thread-safe.
 * </p>
 *
 * TODO: may want to add more bit vector functions like and/or/xor/nand TODO: also might be good to generate boolean[] from byte[] et cetera.
 *
 * @since 1.3
 */
public class BinaryCodec implements BinaryDecoder, BinaryEncoder {

    /*
     * tried to avoid using ArrayUtils to minimize dependencies while using these empty arrays - dep is just not worth it.
     */

    /** Empty char array. */
    private static final char[] EMPTY_CHAR_ARRAY = {};

    /** Empty byte array. */
    private static final byte[] EMPTY_BYTE_ARRAY = {};

    /** Mask for bit 0 of a byte. */
    private static final int BIT_0 = 1;

    /** Mask for bit 1 of a byte. */
    private static final int BIT_1 = 0x02;

    /** Mask for bit 2 of a byte. */
    private static final int BIT_2 = 0x04;

    /** Mask for bit 3 of a byte. */
    private static final int BIT_3 = 0x08;

    /** Mask for bit 4 of a byte. */
    private static final int BIT_4 = 0x10;

    /** Mask for bit 5 of a byte. */
    private static final int BIT_5 = 0x20;

    /** Mask for bit 6 of a byte. */
    private static final int BIT_6 = 0x40;

    /** Mask for bit 7 of a byte. */
    private static final int BIT_7 = 0x80;

    private static final int[] BITS = { BIT_0, BIT_1, BIT_2, BIT_3, BIT_4, BIT_5, BIT_6, BIT_7 };

    /**
     * Decodes a byte array where each byte represents an ASCII '0' or '1'.
     *
     * @param ascii each byte represents an ASCII '0' or '1'.
     * @return the raw encoded binary where each bit corresponds to a byte in the byte array argument.
     */
    public static byte[] fromAscii(final byte[] ascii) {
        if (isEmpty(ascii)) {
            return EMPTY_BYTE_ARRAY;
        }
        final int asciiLength = ascii.length;
        // get length/8 times bytes with 3 bit shifts to the right of the length
        final byte[] raw = new byte[asciiLength >> 3];
        /*
         * We decr index jj by 8 as we go along to not recompute indices using multiplication every time inside the loop.
         */
        for (int ii = 0, jj = asciiLength - 1; ii < raw.length; ii++, jj -= 8) {
            for (int bits = 0; bits < BITS.length; ++bits) {
                if (ascii[jj - bits] == '1') {
                    raw[ii] |= BITS[bits];
                }
            }
        }
        return raw;
    }

    /**
     * Decodes a char array where each char represents an ASCII '0' or '1'.
     *
     * @param ascii each char represents an ASCII '0' or '1'.
     * @return the raw encoded binary where each bit corresponds to a char in the char array argument.
     */
    public static byte[] fromAscii(final char[] ascii) {
        if (ascii == null || ascii.length == 0) {
            return EMPTY_BYTE_ARRAY;
        }
        final int asciiLength = ascii.length;
        // get length/8 times bytes with 3 bit shifts to the right of the length
        final byte[] raw = new byte[asciiLength >> 3];
        /*
         * We decr index jj by 8 as we go along to not recompute indices using multiplication every time inside the loop.
         */
        for (int ii = 0, jj = asciiLength - 1; ii < raw.length; ii++, jj -= 8) {
            for (int bits = 0; bits < BITS.length; ++bits) {
                if (ascii[jj - bits] == '1') {
                    raw[ii] |= BITS[bits];
                }
            }
        }
        return raw;
    }

    /**
     * Returns {@code true} if the given array is {@code null} or empty (size 0.)
     *
     * @param array the source array.
     * @return {@code true} if the given array is {@code null} or empty (size 0.)
     */
    static boolean isEmpty(final byte[] array) {
        return array == null || array.length == 0;
    }

    /**
     * Converts an array of raw binary data into an array of ASCII 0 and 1 character bytes - each byte is a truncated char.
     *
     * @param raw the raw binary data to convert.
     * @return an array of 0 and 1 character bytes for each bit of the argument.
     * @see org.apache.commons.codec.BinaryEncoder#encode(byte[])
     */
    public static byte[] toAsciiBytes(final byte[] raw) {
        if (isEmpty(raw)) {
            return EMPTY_BYTE_ARRAY;
        }
        final int rawLength = raw.length;
        // get 8 times the bytes with 3 bit shifts to the left of the length
        final byte[] ascii = new byte[rawLength << 3];
        /*
         * We decr index jj by 8 as we go along to not recompute indices using multiplication every time inside the loop.
         */
        for (int ii = 0, jj = ascii.length - 1; ii < rawLength; ii++, jj -= 8) {
            for (int bits = 0; bits < BITS.length; ++bits) {
                if ((raw[ii] & BITS[bits]) == 0) {
                    ascii[jj - bits] = '0';
                } else {
                    ascii[jj - bits] = '1';
                }
            }
        }
        return ascii;
    }

    /**
     * Converts an array of raw binary data into an array of ASCII 0 and 1 characters.
     *
     * @param raw the raw binary data to convert.
     * @return an array of 0 and 1 characters for each bit of the argument.
     * @see org.apache.commons.codec.BinaryEncoder#encode(byte[])
     */
    public static char[] toAsciiChars(final byte[] raw) {
        if (isEmpty(raw)) {
            return EMPTY_CHAR_ARRAY;
        }
        final int rawLength = raw.length;
        // get 8 times the bytes with 3 bit shifts to the left of the length
        final char[] ascii = new char[rawLength << 3];
        /*
         * We decr index jj by 8 as we go along to not recompute indices using multiplication every time inside the loop.
         */
        for (int ii = 0, jj = ascii.length - 1; ii < rawLength; ii++, jj -= 8) {
            for (int bits = 0; bits < BITS.length; ++bits) {
                if ((raw[ii] & BITS[bits]) == 0) {
                    ascii[jj - bits] = '0';
                } else {
                    ascii[jj - bits] = '1';
                }
            }
        }
        return ascii;
    }

    /**
     * Converts an array of raw binary data into a String of ASCII 0 and 1 characters.
     *
     * @param raw the raw binary data to convert.
     * @return a String of 0 and 1 characters representing the binary data.
     * @see org.apache.commons.codec.BinaryEncoder#encode(byte[])
     */
    public static String toAsciiString(final byte[] raw) {
        return new String(toAsciiChars(raw));
    }

    /**
     * Constructs a new instance.
     */
    public BinaryCodec() {
        // empty
    }

    /**
     * Decodes a byte array where each byte represents an ASCII '0' or '1'.
     *
     * @param ascii each byte represents an ASCII '0' or '1'.
     * @return the raw encoded binary where each bit corresponds to a byte in the byte array argument.
     * @see org.apache.commons.codec.Decoder#decode(Object)
     */
    @Override
    public byte[] decode(final byte[] ascii) {
        return fromAscii(ascii);
    }

    /**
     * Decodes a byte array where each byte represents an ASCII '0' or '1'.
     *
     * @param ascii each byte represents an ASCII '0' or '1'.
     * @return the raw encoded binary where each bit corresponds to a byte in the byte array argument.
     * @throws DecoderException if argument is not a byte[], char[] or String.
     * @see org.apache.commons.codec.Decoder#decode(Object)
     */
    @Override
    public Object decode(final Object ascii) throws DecoderException {
        if (ascii == null) {
            return EMPTY_BYTE_ARRAY;
        }
        if (ascii instanceof byte[]) {
            return fromAscii((byte[]) ascii);
        }
        if (ascii instanceof char[]) {
            return fromAscii((char[]) ascii);
        }
        if (ascii instanceof String) {
            return fromAscii(((String) ascii).toCharArray());
        }
        throw new DecoderException("argument not a byte array");
    }

    /**
     * Converts an array of raw binary data into an array of ASCII 0 and 1 characters.
     *
     * @param raw the raw binary data to convert.
     * @return 0 and 1 ASCII character bytes one for each bit of the argument.
     * @see org.apache.commons.codec.BinaryEncoder#encode(byte[])
     */
    @Override
    public byte[] encode(final byte[] raw) {
        return toAsciiBytes(raw);
    }

    assertDecodeObject(new byte[0], null);
}

/**
 * Tests for Object decode(Object)
 */
@Test
void testDecodeObjectException() {
    try {
        this.instance.decode(new Object());
    } catch (final DecoderException e) {
        // all is well.
        return;
    }
    fail("Expected DecoderException");
}

/*
 * Tests for byte[] encode(byte[])
 */
@Test
void testEncodeByteArray() {
    // With a single raw binary
    byte[] bits = new byte[1];
    String encoded = new String(instance.encode(bits));
    assertEquals("00000000", encoded);
    bits = new byte[1];
    bits[0] = BIT_0;
    encoded = new String(instance.encode(bits));
    assertEquals("00000001", encoded);
    bits = new byte[1];
    bits[0] = BIT_0 | BIT_1;
    encoded = new String(instance.encode(bits));
    assertEquals("00000011", encoded);
    bits = new byte[1];
    bits[0] = BIT_0 | BIT_1 | BIT_2;
    encoded = new String(instance.encode(bits));
    assertEquals("00000111", encoded);
    bits = new byte[1];
    bits[0] = BIT_0 | BIT_1 | BIT_2 | BIT_3;
    encoded = new String(instance.encode(bits));
    assertEquals("00001111", encoded);
    bits = new byte[1];
    bits[0] = BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4;
    encoded = new String(instance.encode(bits));
    assertEquals("00011111", encoded);
    bits = new byte[1];
    bits[0] = BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5;
    encoded = new String(instance.encode(bits));
    assertEquals("00111111", encoded);
    bits = new byte[1];
    bits[0] = BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6;
    encoded = new String(instance.encode(bits));
    assertEquals("01111111", encoded);
    bits = new byte[1];
    bits[0] = (byte) (BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6 | BIT_7);
    encoded = new String(instance.encode(bits));
    assertEquals("11111111", encoded);
    // With a two raw binaries
    bits = new byte[2];
    encoded = new String(instance.encode(bits));
    assertEquals("0000000000000000", encoded);
    bits = new byte[2];
    bits[0] = BIT_0;
    encoded = new String(instance.encode(bits));
    assertEquals("0000000000000001", encoded);
    bits = new byte[2];
    bits[0] = BIT_0 | BIT_1;
    encoded = new String(instance.encode(bits));
    assertEquals("0000000000000011", encoded);
    bits = new byte[2];
    bits[0] = BIT_0 | BIT_1 | BIT_2;
    encoded = new String(instance.encode(bits));
    assertEquals("0000000000000111", encoded);
    bits = new byte[2];
    bits[0] = BIT_0 | BIT_1 | BIT_2 | BIT_3;
    encoded = new String(instance.encode(bits));
    assertEquals("0000000000001111", encoded);
    bits = new byte[2];
    bits[0] = BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4;
    encoded = new String(instance.encode(bits));
    assertEquals("0000000000011111", encoded);
    bits = new byte[2];
    bits[0] = BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5;
    encoded = new String(instance.encode(bits));
    assertEquals("0000000000111111", encoded);
    bits = new byte[2];
    bits[0] = BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6;
    encoded = new String(instance.encode(bits));
    assertEquals("0000000001111111", encoded);
    bits = new byte[2];
    bits[0] = (byte) (BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6 | BIT_7);
    encoded = new String(instance.encode(bits));
    assertEquals("0000000011111111", encoded);
    // work on the other byte now
